def count_paths(Y, X, x_init, grid):
    # Directions: (dy, dx)
    directions = [(-1, 0), (0, 1), (0, -1)]  # Up, East, West
    memo = {}

    def dfs(y, x):
        if (y, x) in memo:
            return memo[(y, x)]

        if grid[y][x] == '@':
            return 1

        total_paths = 0
        for dy, dx in directions:
            ny, nx = y + dy, x + dx
            if 0 <= ny < Y and 0 <= nx < X and grid[ny][nx] != '#':
                if grid[y][x] == '>' and dx == 1:
                    total_paths = (total_paths + dfs(ny, nx)) % MOD
                elif grid[y][x] == '<' and dx == -1:
                    total_paths = (total_paths + dfs(ny, nx)) % MOD
                elif grid[y][x] in '~>':
                    total_paths = (total_paths + dfs(ny, nx)) % MOD

        memo[(y, x)] = total_paths
        return total_paths

    result = dfs(Y - 1, x_init)
    return result if result > 0 else "begin repairs"

