        for x in range(X):
            if grid[y][x] == '#':
                continue

            # Move north by lowering the sails
            if y + 1 < Y and grid[y + 1][x] != '#':
                dp[y][x] = (dp[y][x] + dp[y + 1][x]) % MOD

            # Move east or west based on current
            if grid[y][x] == '>':
                if x + 1 < X and grid[y][x + 1] != '#':
                    dp[y][x] = (dp[y][x] + dp[y][x + 1]) % MOD
            elif grid[y][x] == '<':
                if x - 1 >= 0 and grid[y][x - 1] != '#':
                    dp[y][x] = (dp[y][x] + dp[y][x - 1]) % MOD

    # Output the result
    result = dp[0][x_init]
    if result == 0:
        print("begin repairs")
    else:
        print(result)
